// Severity and CVSS are not written here: they are derived from the
// advisory's ratings by SetAdvisoryRating once its sources are stored
// (ADR-038 §2).
func (q *Queries) UpsertAdvisory(ctx context.Context, arg UpsertAdvisoryParams) (Advisory, error) {
	row := q.db.QueryRowContext(ctx, upsertAdvisory,
		arg.CanonicalID,
		arg.Title,
		arg.Description,
		arg.IsMalware,
		arg.MalwareType,
		arg.PublishedAt,
		arg.WithdrawnAt,
	)
	var i Advisory
	err := row.Scan(
		&i.ID,
		&i.CanonicalID,
		&i.Title,
		&i.Description,
		&i.Severity,
		&i.CvssScore,
		&i.CvssVersion,
		&i.CvssVector,
		&i.IsMalware,
		&i.MalwareType,
		&i.PublishedAt,
		&i.WithdrawnAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RatedBy,
	)
	return i, err
}

const upsertAdvisoryAlias = `-- name: UpsertAdvisoryAlias :exec
INSERT INTO advisory_aliases (advisory_id, alias)
VALUES ($1, $2)
ON CONFLICT (alias) DO NOTHING
`

type UpsertAdvisoryAliasParams struct {
	AdvisoryID uuid.UUID `json:"advisory_id"`
	Alias      string    `json:"alias"`
}

func (q *Queries) UpsertAdvisoryAlias(ctx context.Context, arg UpsertAdvisoryAliasParams) error {
	_, err := q.db.ExecContext(ctx, upsertAdvisoryAlias, arg.AdvisoryID, arg.Alias)
	return err
}

const upsertAdvisorySource = `-- name: UpsertAdvisorySource :one
INSERT INTO advisory_sources (advisory_id, provider, provider_id, raw_data, fetched_at, ratings_version)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (advisory_id, provider) DO UPDATE SET
    provider_id = EXCLUDED.provider_id,
    raw_data = EXCLUDED.raw_data,
    fetched_at = EXCLUDED.fetched_at,
    ratings_version = EXCLUDED.ratings_version
RETURNING id
`

type UpsertAdvisorySourceParams struct {
	AdvisoryID     uuid.UUID       `json:"advisory_id"`
	Provider       string          `json:"provider"`
	ProviderID     string          `json:"provider_id"`
	RawData        json.RawMessage `json:"raw_data"`
	FetchedAt      time.Time       `json:"fetched_at"`
	RatingsVersion int16           `json:"ratings_version"`
}

func (q *Queries) UpsertAdvisorySource(ctx context.Context, arg UpsertAdvisorySourceParams) (uuid.UUID, error) {
	row := q.db.QueryRowContext(ctx, upsertAdvisorySource,
		arg.AdvisoryID,
		arg.Provider,
		arg.ProviderID,
		arg.RawData,
		arg.FetchedAt,
		arg.RatingsVersion,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}
